// =====================================================================
// Config & Safety Gate
// Reads every setting from environment variables and resolves the
// effective execution mode. SAFE BY DEFAULT: if a variable is missing,
// or env access is blocked, the workflow runs in sandbox + dry-run with
// all CRM writes and outbound alerts disabled.
// Secrets are NEVER copied into execution data — only presence booleans.
// =====================================================================
let envAccessible = true;
try { void $env.SANDBOX_MODE; } catch (e) { envAccessible = false; }

const readEnv = (name) => {
  try {
    const v = $env[name];
    if (v === undefined || v === null) return undefined;
    const s = String(v).trim();
    return s === '' ? undefined : s;
  } catch (e) {
    return undefined;
  }
};
const bool = (name, dflt) => {
  const v = readEnv(name);
  if (v === undefined) return dflt;
  return ['true', '1', 'yes', 'on'].includes(v.toLowerCase());
};
const num = (name, dflt) => {
  const v = readEnv(name);
  if (v === undefined) return dflt;
  const n = Number(v);
  return Number.isFinite(n) ? n : dflt;
};
const str = (name, dflt) => {
  const v = readEnv(name);
  return v === undefined ? dflt : v;
};
const list = (name, dflt) => {
  const v = readEnv(name);
  if (v === undefined) return dflt;
  return v.split(',').map((x) => x.trim()).filter(Boolean);
};
const jsonEnv = (name, dflt, warnings) => {
  const v = readEnv(name);
  if (v === undefined) return dflt;
  try { return JSON.parse(v); } catch (e) {
    warnings.push(`${name} is not valid JSON; using built-in default.`);
    return dflt;
  }
};

const warnings = [];
if (!envAccessible) {
  warnings.push('Environment variable access is blocked (N8N_BLOCK_ENV_ACCESS_IN_NODE=true). Running with safe defaults: sandbox + dry-run.');
}

// ---------- Safety flags (safe defaults) ----------
const sandboxMode = bool('SANDBOX_MODE', true);
const dryRun = bool('DRY_RUN', true);
const scoreUpdateEnabled = bool('SCORE_UPDATE_ENABLED', false);
const sendSlackAlerts = bool('SEND_SLACK_ALERTS', false);
const sendAuditWebhook = bool('SEND_AUDIT_WEBHOOK', false);

const hasHubspotToken = readEnv('HUBSPOT_ACCESS_TOKEN') !== undefined;
const hasSlackWebhook = readEnv('SLACK_SCORING_WEBHOOK_URL') !== undefined;
const hasAuditWebhook = readEnv('ALERT_WEBHOOK_URL') !== undefined;

if (!sandboxMode && !hasHubspotToken) {
  throw new Error('SANDBOX_MODE=false requires HUBSPOT_ACCESS_TOKEN. Set the token or switch SANDBOX_MODE back to true.');
}

let writeMode = 'live';
if (sandboxMode) writeMode = 'sandbox';
else if (dryRun) writeMode = 'dry_run';
else if (!scoreUpdateEnabled) writeMode = 'updates_disabled';
else if (!hasHubspotToken) writeMode = 'missing_token';
const liveWrite = writeMode === 'live';

const slackLive = sendSlackAlerts && !dryRun && hasSlackWebhook;
const auditWebhookLive = sendAuditWebhook && !dryRun && hasAuditWebhook;
if (sendSlackAlerts && !hasSlackWebhook) warnings.push('SEND_SLACK_ALERTS=true but SLACK_SCORING_WEBHOOK_URL is not set; Slack disabled.');
if (sendAuditWebhook && !hasAuditWebhook) warnings.push('SEND_AUDIT_WEBHOOK=true but ALERT_WEBHOOK_URL is not set; audit webhook disabled.');
if (sendSlackAlerts && dryRun) warnings.push('SEND_SLACK_ALERTS=true is ignored while DRY_RUN=true (preview only).');

// ---------- Scoring weights (normalized to sum = 1) ----------
const rawWeights = {
  headcountGrowth: Math.max(0, num('WEIGHT_HEADCOUNT_GROWTH', 0.30)),
  funding: Math.max(0, num('WEIGHT_FUNDING', 0.30)),
  technographic: Math.max(0, num('WEIGHT_TECHNOGRAPHIC', 0.25)),
  firmographic: Math.max(0, num('WEIGHT_FIRMOGRAPHIC', 0.15)),
};
let weightSum = Object.values(rawWeights).reduce((a, b) => a + b, 0);
if (weightSum <= 0) {
  warnings.push('All scoring weights are zero; falling back to default weights.');
  Object.assign(rawWeights, { headcountGrowth: 0.30, funding: 0.30, technographic: 0.25, firmographic: 0.15 });
  weightSum = 1;
}
const weights = {};
for (const [k, v] of Object.entries(rawWeights)) weights[k] = Math.round((v / weightSum) * 10000) / 10000;

// ---------- Tier thresholds ----------
const tiers = {
  tier1Min: num('TIER_1_MIN_SCORE', 80),
  tier2Min: num('TIER_2_MIN_SCORE', 60),
  tier3Min: num('TIER_3_MIN_SCORE', 40),
  hysteresisPoints: Math.max(0, num('TIER_HYSTERESIS_POINTS', 3)),
};
if (!(tiers.tier1Min > tiers.tier2Min && tiers.tier2Min > tiers.tier3Min && tiers.tier3Min >= 0 && tiers.tier1Min <= 100)) {
  throw new Error(`Invalid tier thresholds: require 100 >= TIER_1_MIN_SCORE (${tiers.tier1Min}) > TIER_2_MIN_SCORE (${tiers.tier2Min}) > TIER_3_MIN_SCORE (${tiers.tier3Min}) >= 0.`);
}

// ---------- Signal matrices ----------
const defaultStagePoints = { seed: 45, series_a: 65, series_b: 85, series_c: 100, series_d_plus: 80, ipo: 40, none: 0 };
const defaultTechMatrix = {
  crm: { hubspot: 40, salesforce: 30, pipedrive: 15 },
  cloud_hosting: { aws: 25, gcp: 25, azure: 25 },
  data_stack: { snowflake: 15, segment: 15, bigquery: 10 },
  automation: { n8n: 10, zapier: 5, make: 5 },
  negative_signals: { legacy_on_prem_crm: -25 },
};

const scoring = {
  weights,
  tiers,
  minComponents: Math.max(1, Math.min(4, num('MIN_SIGNAL_COMPONENTS', 2))),
  driftThreshold: Math.max(0, num('SCORE_DRIFT_THRESHOLD', 5)),
  staleAfterDays: Math.max(1, num('STALE_SCORE_REFRESH_DAYS', 28)),
  writePolicy: str('WRITE_POLICY', 'changes_only') === 'all' ? 'all' : 'changes_only',
  headcount: {
    growthCeilingPct: Math.max(0.1, num('HEADCOUNT_GROWTH_CEILING_PCT', 3)),
    declineFloorPct: Math.min(-0.1, num('HEADCOUNT_DECLINE_FLOOR_PCT', -3)),
    flatScore: Math.min(100, Math.max(0, num('HEADCOUNT_FLAT_SCORE', 40))),
    maxBaselineAgeDays: Math.max(7, num('HEADCOUNT_MAX_BASELINE_AGE_DAYS', 35)),
  },
  funding: {
    stagePoints: jsonEnv('FUNDING_STAGE_POINTS_JSON', defaultStagePoints, warnings),
    fullCreditDays: Math.max(0, num('FUNDING_FULL_CREDIT_DAYS', 90)),
    decayDays: Math.max(1, num('FUNDING_DECAY_DAYS', 540)),
    floorMultiplier: Math.min(1, Math.max(0, num('FUNDING_FLOOR_MULTIPLIER', 0.15))),
    unknownDateMultiplier: Math.min(1, Math.max(0, num('FUNDING_UNKNOWN_DATE_MULTIPLIER', 0.5))),
  },
  techMatrix: jsonEnv('TECH_MATRIX_JSON', defaultTechMatrix, warnings),
  firmographic: {
    employeeMin: Math.max(1, num('ICP_EMPLOYEE_MIN', 50)),
    employeeMax: Math.max(2, num('ICP_EMPLOYEE_MAX', 2000)),
    targetIndustries: list('ICP_TARGET_INDUSTRIES', [
      'LOGISTICS_AND_SUPPLY_CHAIN', 'COMPUTER_SOFTWARE', 'HOSPITAL_HEALTH_CARE', 'INFORMATION_TECHNOLOGY_AND_SERVICES',
    ]).map((x) => x.toUpperCase()),
    offTargetIndustryScore: Math.min(100, Math.max(0, num('ICP_OFF_TARGET_INDUSTRY_SCORE', 30))),
    employeeBandWeight: 0.6,
    industryWeight: 0.4,
  },
};
if (scoring.funding.decayDays <= scoring.funding.fullCreditDays) {
  scoring.funding.decayDays = scoring.funding.fullCreditDays + 1;
  warnings.push('FUNDING_DECAY_DAYS must exceed FUNDING_FULL_CREDIT_DAYS; adjusted automatically.');
}

// ---------- HubSpot property mapping (override to match your portal) ----------
const properties = {
  score: str('HS_PROP_ICP_SCORE', 'icp_fit_score'),
  tier: str('HS_PROP_ACCOUNT_TIER', 'icp_account_tier'),
  recalculatedAt: str('HS_PROP_RECALCULATED_AT', 'icp_last_recalculated_at'),
  scoreDelta: str('HS_PROP_SCORE_DELTA', 'icp_score_delta'),
  scoreBreakdown: str('HS_PROP_SCORE_BREAKDOWN', 'icp_score_breakdown'),
  headcountBaseline: str('HS_PROP_HEADCOUNT_BASELINE', 'icp_headcount_baseline'),
  headcountBaselineDate: str('HS_PROP_HEADCOUNT_BASELINE_DATE', 'icp_headcount_baseline_date'),
  fundingStage: str('HS_PROP_FUNDING_STAGE', 'latest_funding_stage'),
  fundingDate: str('HS_PROP_FUNDING_DATE', 'latest_funding_date'),
  fundingAmount: str('HS_PROP_FUNDING_AMOUNT', 'latest_funding_amount_usd'),
  techStack: str('HS_PROP_TECH_STACK', 'technographic_stack'),
};
const scoringScopeProperty = str('SCORING_SCOPE_PROPERTY', '');
const hubspotReadProperties = [...new Set([
  'name', 'domain', 'industry', 'country', 'numberofemployees', 'hubspot_owner_id',
  properties.score, properties.tier, properties.recalculatedAt,
  properties.headcountBaseline, properties.headcountBaselineDate,
  properties.fundingStage, properties.fundingDate, properties.fundingAmount, properties.techStack,
  ...(scoringScopeProperty ? [scoringScopeProperty] : []),
])];

const runStartedAt = new Date().toISOString();
let executionId = 'manual';
try { executionId = String($execution.id); } catch (e) { /* not available in some contexts */ }

return [{
  json: {
    runId: `icp-recalc-${runStartedAt.replace(/[-:.TZ]/g, '').slice(0, 14)}-${executionId}`,
    runStartedAt,
    referenceDateOverride: str('SCORING_REFERENCE_DATE', null),
    envAccessible,
    sandboxMode,
    dryRun,
    scoreUpdateEnabled,
    sendSlackAlerts,
    sendAuditWebhook,
    liveRead: !sandboxMode,
    liveWrite,
    writeMode,
    slackLive,
    auditWebhookLive,
    credentialsPresent: { hubspotAccessToken: hasHubspotToken, slackWebhook: hasSlackWebhook, auditWebhook: hasAuditWebhook },
    hubspot: {
      apiBaseUrl: str('HUBSPOT_API_BASE_URL', 'https://api.hubapi.com').replace(/\/+$/, ''),
      portalId: str('HUBSPOT_PORTAL_ID', '99000001'),
      batchSize: Math.min(100, Math.max(1, num('HUBSPOT_BATCH_SIZE', 100))),
      pageSize: Math.min(100, Math.max(1, num('HUBSPOT_PAGE_SIZE', 100))),
    },
    hubspotReadProperties,
    hubspotReadPropertiesCsv: hubspotReadProperties.join(','),
    scoringScopeProperty,
    properties,
    scoring,
    safety: {
      maxWritesPerRun: Math.max(1, num('MAX_WRITES_PER_RUN', 500)),
      maxTierChangeRatio: Math.min(1, Math.max(0, num('MAX_TIER_CHANGE_RATIO', 0.35))),
      circuitBreakerMinSample: Math.max(1, num('CIRCUIT_BREAKER_MIN_SAMPLE', 20)),
    },
    slack: {
      channelLabel: str('SLACK_CHANNEL_LABEL', '#revops-scoring'),
      maxListItems: Math.min(15, Math.max(1, num('SLACK_MAX_LIST_ITEMS', 8))),
    },
    warnings,
  },
}];

// =====================================================================
// Normalize Company Signals
// Flattens one or more HubSpot list pages (live, paginated) or the
// synthetic fixture page into one item per company with typed signals.
// =====================================================================
const cfg = $('Config & Safety Gate').first().json;
const P = cfg.properties;
const pages = $input.all().map((i) => i.json || {});

const toStr = (v) => (v === undefined || v === null || String(v).trim() === '' ? null : String(v).trim());
const toNum = (v) => {
  const s = toStr(v);
  if (s === null) return null;
  const n = Number(s.replace(/,/g, ''));
  return Number.isFinite(n) ? n : null;
};
const toIso = (v) => {
  const s = toStr(v);
  if (s === null) return null;
  const d = /^\d{10,}$/.test(s) ? new Date(Number(s)) : new Date(s);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
};
const toList = (v) => {
  const s = toStr(v);
  if (s === null) return [];
  return [...new Set(s.split(/[;,]/).map((x) => x.trim().toLowerCase().replace(/\s+/g, '_')).filter(Boolean))];
};
const normalizeStage = (v) => {
  const s = toStr(v);
  if (s === null) return null;
  const k = s.toLowerCase().replace(/[\s-]+/g, '_');
  if (['pre_seed', 'preseed', 'seed', 'angel'].includes(k)) return 'seed';
  if (['series_a', 'a'].includes(k)) return 'series_a';
  if (['series_b', 'b'].includes(k)) return 'series_b';
  if (['series_c', 'c'].includes(k)) return 'series_c';
  if (/^series_[d-z]/.test(k) || ['series_d_plus', 'growth', 'late_stage', 'private_equity'].includes(k)) return 'series_d_plus';
  if (['ipo', 'public', 'post_ipo'].includes(k)) return 'ipo';
  if (['none', 'bootstrapped', 'unfunded', 'no_funding'].includes(k)) return 'none';
  return 'unknown';
};

let referenceDate = null;
const records = [];
for (const page of pages) {
  if (page.meta && page.meta.asOf && cfg.sandboxMode) referenceDate = page.meta.asOf;
  if (Array.isArray(page.results)) records.push(...page.results);
}

const stats = { pagesRead: pages.length, recordsRead: records.length, duplicates: 0, archived: 0, outOfScope: 0, invalid: 0, normalized: 0 };
const seen = new Set();
const out = [];

for (const r of records) {
  if (!r || r.id === undefined || r.id === null) { stats.invalid++; continue; }
  const id = String(r.id);
  if (seen.has(id)) { stats.duplicates++; continue; }
  seen.add(id);
  if (r.archived === true) { stats.archived++; continue; }
  const p = r.properties || {};
  if (cfg.scoringScopeProperty) {
    const flag = toStr(p[cfg.scoringScopeProperty]);
    if (!flag || !['true', 'yes', '1'].includes(flag.toLowerCase())) { stats.outOfScope++; continue; }
  }
  out.push({
    companyId: id,
    name: toStr(p.name) || `Company ${id}`,
    domain: toStr(p.domain),
    industry: toStr(p.industry) ? toStr(p.industry).toUpperCase() : null,
    country: toStr(p.country),
    ownerId: toStr(p.hubspot_owner_id),
    employeesCurrent: toNum(p.numberofemployees),
    employeesBaseline: toNum(p[P.headcountBaseline]),
    baselineDate: toIso(p[P.headcountBaselineDate]),
    fundingStage: normalizeStage(p[P.fundingStage]),
    fundingDate: toIso(p[P.fundingDate]),
    fundingAmountUsd: toNum(p[P.fundingAmount]),
    technographics: toList(p[P.techStack]),
    previousScore: toNum(p[P.score]),
    previousTierRaw: toStr(p[P.tier]),
    previousCalculatedAt: toIso(p[P.recalculatedAt]),
    source: cfg.sandboxMode ? 'synthetic_fixture' : 'hubspot_api',
  });
}
stats.normalized = out.length;

const ingest = { ...stats, referenceDate };
if (out.length === 0) {
  return [{ json: { _noRecords: true, _ingest: ingest } }];
}
return out.map((c) => ({ json: { ...c, _ingest: ingest } }));

// =====================================================================
// Account Scoring & Tier Recalibration Engine
// Composite ICP fit score (0-100) from four weighted components:
//   1. Headcount growth velocity (weekly-equivalent % change vs baseline)
//   2. Funding signal (stage points x recency decay)
//   3. Technographic match (category-capped tech matrix, with penalties)
//   4. Firmographic fit (employee band + target industry)
// Missing components are excluded and remaining weights renormalized.
// Tiers use hysteresis on downgrades to prevent week-to-week flapping.
// Drift and tier changes are measured against the last stored values.
// =====================================================================
const cfg = $('Config & Safety Gate').first().json;
const S = cfg.scoring;
const P = cfg.properties;
const inputs = $input.all().map((i) => i.json);

if (inputs.length === 1 && inputs[0]._noRecords) {
  return [{ json: { _noRecords: true, _ingest: inputs[0]._ingest } }];
}

const DAY = 86400000;
const ingest = inputs[0]._ingest || {};
const referenceIso = cfg.referenceDateOverride || ingest.referenceDate || cfg.runStartedAt;
const ref = new Date(referenceIso);
if (Number.isNaN(ref.getTime())) throw new Error(`Invalid scoring reference date: ${referenceIso}`);

const round1 = (n) => Math.round(n * 10) / 10;
const clamp = (n, lo, hi) => Math.min(hi, Math.max(lo, n));

const TIERS = [
  { label: 'Tier 1', value: 'tier_1', rank: 3, min: S.tiers.tier1Min },
  { label: 'Tier 2', value: 'tier_2', rank: 2, min: S.tiers.tier2Min },
  { label: 'Tier 3', value: 'tier_3', rank: 1, min: S.tiers.tier3Min },
  { label: 'Unqualified', value: 'unqualified', rank: 0, min: -Infinity },
];
const tierForScore = (score) => TIERS.find((t) => score >= t.min);
const parseTier = (raw) => {
  if (!raw) return null;
  const k = String(raw).toLowerCase().replace(/[\s-]+/g, '_');
  if (['tier_1', 'tier1', '1', 't1'].includes(k)) return TIERS[0];
  if (['tier_2', 'tier2', '2', 't2'].includes(k)) return TIERS[1];
  if (['tier_3', 'tier3', '3', 't3'].includes(k)) return TIERS[2];
  if (['unqualified', 'none', 'not_icp', '0'].includes(k)) return TIERS[3];
  return null;
};

// ---------- Component 1: headcount growth velocity ----------
function headcountComponent(c, flags) {
  const H = S.headcount;
  if (c.employeesCurrent === null) { flags.push('missing_headcount'); return { available: false, reason: 'missing_headcount' }; }
  if (c.employeesBaseline === null || c.employeesBaseline <= 0) { flags.push('missing_headcount_baseline'); return { available: false, reason: 'missing_baseline' }; }
  let days = 7;
  if (c.baselineDate) {
    days = (ref - new Date(c.baselineDate)) / DAY;
    if (days < 1) days = 1;
  } else {
    flags.push('baseline_date_assumed_7d');
  }
  if (days > H.maxBaselineAgeDays) { flags.push('stale_headcount_baseline'); return { available: false, reason: 'stale_baseline', baselineAgeDays: round1(days) }; }
  const totalPct = ((c.employeesCurrent - c.employeesBaseline) / c.employeesBaseline) * 100;
  const weeklyPct = totalPct / (days / 7);
  let score;
  if (weeklyPct >= H.growthCeilingPct) score = 100;
  else if (weeklyPct <= H.declineFloorPct) score = 0;
  else if (weeklyPct >= 0) score = H.flatScore + (weeklyPct / H.growthCeilingPct) * (100 - H.flatScore);
  else score = H.flatScore * (1 - weeklyPct / H.declineFloorPct);
  return {
    available: true,
    score: round1(clamp(score, 0, 100)),
    detail: { headcountDelta: c.employeesCurrent - c.employeesBaseline, totalPct: round1(totalPct), weeklyPct: Math.round(weeklyPct * 100) / 100, baselineAgeDays: round1(days) },
  };
}

// ---------- Component 2: funding signal ----------
function fundingComponent(c, flags) {
  const F = S.funding;
  if (c.fundingStage === null) { flags.push('missing_funding'); return { available: false, reason: 'missing_funding' }; }
  if (c.fundingStage === 'unknown') flags.push('unrecognized_funding_stage');
  const base = Number(F.stagePoints[c.fundingStage] ?? 0);
  if (c.fundingStage === 'none') return { available: true, score: 0, detail: { stage: 'none', basePoints: 0, recencyMultiplier: 0, ageDays: null } };
  let ageDays = null;
  let mult;
  if (!c.fundingDate) {
    mult = F.unknownDateMultiplier;
    flags.push('funding_date_unknown');
  } else {
    ageDays = (ref - new Date(c.fundingDate)) / DAY;
    if (ageDays < 0) { flags.push('funding_date_in_future'); mult = 1; }
    else if (ageDays <= F.fullCreditDays) mult = 1;
    else if (ageDays >= F.decayDays) mult = F.floorMultiplier;
    else mult = 1 - (1 - F.floorMultiplier) * ((ageDays - F.fullCreditDays) / (F.decayDays - F.fullCreditDays));
  }
  return {
    available: true,
    score: round1(clamp(base * mult, 0, 100)),
    detail: { stage: c.fundingStage, basePoints: base, recencyMultiplier: Math.round(mult * 1000) / 1000, ageDays: ageDays === null ? null : Math.round(ageDays), amountUsd: c.fundingAmountUsd },
  };
}

// ---------- Component 3: technographic match ----------
function technographicComponent(c, flags) {
  if (!c.technographics.length) { flags.push('missing_technographics'); return { available: false, reason: 'missing_technographics' }; }
  const matched = [];
  let raw = 0;
  let maxPossible = 0;
  for (const [category, techs] of Object.entries(S.techMatrix || {})) {
    const entries = Object.entries(techs || {}).map(([t, pts]) => [String(t).toLowerCase(), Number(pts) || 0]);
    const positives = entries.filter(([, pts]) => pts > 0);
    if (positives.length) maxPossible += Math.max(...positives.map(([, pts]) => pts));
    let bestPositive = 0;
    let negatives = 0;
    for (const [tech, pts] of entries) {
      if (!c.technographics.includes(tech)) continue;
      matched.push({ category, tech, points: pts });
      if (pts > 0) bestPositive = Math.max(bestPositive, pts);
      else negatives += pts;
    }
    raw += bestPositive + negatives;
  }
  const score = maxPossible > 0 ? clamp((raw / maxPossible) * 100, 0, 100) : 0;
  return { available: true, score: round1(score), detail: { rawPoints: raw, maxPossible, matched, unmatched: c.technographics.filter((t) => !matched.some((m) => m.tech === t)) } };
}

// ---------- Component 4: firmographic fit ----------
function firmographicComponent(c, flags) {
  const Fm = S.firmographic;
  const parts = [];
  const detail = {};
  if (c.employeesCurrent !== null) {
    let band;
    if (c.employeesCurrent >= Fm.employeeMin && c.employeesCurrent <= Fm.employeeMax) band = 100;
    else if (c.employeesCurrent < Fm.employeeMin) band = (c.employeesCurrent / Fm.employeeMin) * 100;
    else band = Math.max(20, (Fm.employeeMax / c.employeesCurrent) * 100);
    parts.push({ score: band, w: Fm.employeeBandWeight });
    detail.employeeBandScore = round1(band);
  }
  if (c.industry) {
    const hit = Fm.targetIndustries.includes(c.industry);
    parts.push({ score: hit ? 100 : Fm.offTargetIndustryScore, w: Fm.industryWeight });
    detail.industryMatch = hit;
  }
  if (!parts.length) { flags.push('missing_firmographics'); return { available: false, reason: 'missing_firmographics' }; }
  const wSum = parts.reduce((a, p) => a + p.w, 0);
  const score = parts.reduce((a, p) => a + p.score * p.w, 0) / wSum;
  return { available: true, score: round1(clamp(score, 0, 100)), detail };
}

const out = [];
for (const c of inputs) {
  if (!c.companyId) continue;
  const flags = [];
  const components = {
    headcountGrowth: headcountComponent(c, flags),
    funding: fundingComponent(c, flags),
    technographic: technographicComponent(c, flags),
    firmographic: firmographicComponent(c, flags),
  };
  let availableWeight = 0;
  let weighted = 0;
  let availableCount = 0;
  for (const [key, comp] of Object.entries(components)) {
    comp.weight = S.weights[key];
    if (comp.available) {
      availableCount++;
      availableWeight += comp.weight;
      weighted += comp.score * comp.weight;
    }
  }
  for (const comp of Object.values(components)) {
    comp.effectiveWeight = comp.available && availableWeight > 0 ? Math.round((comp.weight / availableWeight) * 10000) / 10000 : 0;
  }
  const dataCompleteness = Math.round(availableWeight * 100);
  const insufficientData = availableCount < S.minComponents || availableWeight <= 0;

  let previousTier = parseTier(c.previousTierRaw);
  if (!previousTier && c.previousScore !== null) previousTier = tierForScore(c.previousScore);
  if (c.previousTierRaw && !parseTier(c.previousTierRaw)) flags.push('unrecognized_previous_tier');

  let compositeScore = null;
  let rawTier = null;
  let tier = previousTier;
  let hysteresisHeld = false;
  let tierChange;
  let scoreDelta = null;
  let driftDetected = false;

  if (insufficientData) {
    tierChange = 'insufficient_data';
  } else {
    compositeScore = round1(weighted / availableWeight);
    rawTier = tierForScore(compositeScore);
    tier = rawTier;
    if (previousTier && rawTier.rank < previousTier.rank && Number.isFinite(previousTier.min)
        && compositeScore >= previousTier.min - S.tiers.hysteresisPoints) {
      tier = previousTier;
      hysteresisHeld = true;
    }
    if (!previousTier) tierChange = 'initial';
    else if (tier.rank > previousTier.rank) tierChange = 'upgrade';
    else if (tier.rank < previousTier.rank) tierChange = 'downgrade';
    else tierChange = hysteresisHeld ? 'held_by_hysteresis' : 'unchanged';
    if (c.previousScore !== null) {
      scoreDelta = round1(compositeScore - c.previousScore);
      driftDetected = Math.abs(scoreDelta) >= S.driftThreshold;
    }
  }

  let shouldWrite = false;
  let writeReason = 'no_material_change';
  const lastCalcAgeDays = c.previousCalculatedAt ? (ref - new Date(c.previousCalculatedAt)) / DAY : null;
  if (insufficientData) writeReason = 'insufficient_data';
  else if (S.writePolicy === 'all') { shouldWrite = true; writeReason = 'policy_all'; }
  else if (tierChange === 'initial') { shouldWrite = true; writeReason = 'first_score'; }
  else if (tierChange === 'upgrade' || tierChange === 'downgrade') { shouldWrite = true; writeReason = 'tier_change'; }
  else if (driftDetected) { shouldWrite = true; writeReason = 'score_drift'; }
  else if (lastCalcAgeDays === null || lastCalcAgeDays >= S.staleAfterDays) { shouldWrite = true; writeReason = 'refresh_stale'; }

  let hubspotUpdate = null;
  if (shouldWrite) {
    const abbreviations = { headcountGrowth: 'HC', funding: 'FD', technographic: 'TG', firmographic: 'FM' };
    const breakdown = Object.entries(components)
      .map(([k, v]) => `${abbreviations[k]}:${v.available ? v.score : 'na'}`)
      .join('|') + `|DC:${dataCompleteness}%`;
    const properties = {
      [P.score]: compositeScore,
      [P.tier]: tier.value,
      [P.recalculatedAt]: cfg.runStartedAt,
    };
    if (P.scoreDelta && scoreDelta !== null) properties[P.scoreDelta] = scoreDelta;
    if (P.scoreBreakdown) properties[P.scoreBreakdown] = breakdown;
    if (c.employeesCurrent !== null && P.headcountBaseline) {
      properties[P.headcountBaseline] = c.employeesCurrent;
      if (P.headcountBaselineDate) properties[P.headcountBaselineDate] = ref.toISOString().slice(0, 10);
    }
    hubspotUpdate = { id: c.companyId, properties };
  }

  out.push({
    json: {
      companyId: c.companyId,
      name: c.name,
      domain: c.domain,
      industry: c.industry,
      ownerId: c.ownerId,
      source: c.source,
      referenceDate: ref.toISOString(),
      compositeScore,
      previousScore: c.previousScore,
      scoreDelta,
      driftDetected,
      rawTier: rawTier ? rawTier.label : null,
      tier: tier ? tier.label : null,
      tierValue: tier ? tier.value : null,
      previousTier: previousTier ? previousTier.label : null,
      tierChange,
      hysteresisHeld,
      dataCompleteness,
      insufficientData,
      dataQualityFlags: flags,
      components,
      shouldWrite,
      writeReason,
      hubspotUpdate,
      _ingest: ingest,
    },
  });
}
return out.length ? out : [{ json: { _noRecords: true, _ingest: ingest } }];

// =====================================================================
// Build HubSpot Batch Payloads
// Chunks write-eligible updates into /crm/v3/objects/companies/batch/update
// payloads (max 100 inputs each) and applies circuit breakers:
//   - MAX_WRITES_PER_RUN caps the blast radius of a single run
//   - MAX_TIER_CHANGE_RATIO blocks writes when an abnormal share of
//     accounts change tier (usually a broken enrichment feed)
// =====================================================================
const cfg = $('Config & Safety Gate').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r.companyId);

const writable = rows.filter((r) => r.shouldWrite && r.hubspotUpdate);
const withPreviousTier = rows.filter((r) => r.previousTier && !r.insufficientData);
const tierMoves = withPreviousTier.filter((r) => r.tierChange === 'upgrade' || r.tierChange === 'downgrade').length;
const tierChangeRatio = withPreviousTier.length ? tierMoves / withPreviousTier.length : 0;

let blockReason = null;
if (writable.length > cfg.safety.maxWritesPerRun) {
  blockReason = `Circuit breaker: ${writable.length} writes exceed MAX_WRITES_PER_RUN (${cfg.safety.maxWritesPerRun}).`;
} else if (withPreviousTier.length >= cfg.safety.circuitBreakerMinSample && tierChangeRatio > cfg.safety.maxTierChangeRatio) {
  blockReason = `Circuit breaker: ${(tierChangeRatio * 100).toFixed(1)}% of accounts changed tier (limit ${(cfg.safety.maxTierChangeRatio * 100).toFixed(0)}%). Check enrichment feeds before writing.`;
}

let writeMode = cfg.writeMode;
if (writeMode === 'live' && blockReason) writeMode = 'blocked';
const liveWrite = writeMode === 'live';

const guard = {
  writableCount: writable.length,
  scoredWithPreviousTier: withPreviousTier.length,
  tierMoves,
  tierChangeRatio: Math.round(tierChangeRatio * 1000) / 1000,
  blockReason,
};

if (!writable.length) {
  return [{ json: { batchIndex: 0, batchCount: 0, inputCount: 0, liveWrite: false, writeMode: 'no_changes', configuredWriteMode: cfg.writeMode, guard, payload: { inputs: [] } } }];
}

const size = cfg.hubspot.batchSize;
const chunks = [];
for (let i = 0; i < writable.length; i += size) chunks.push(writable.slice(i, i + size));

return chunks.map((chunk, idx) => ({
  json: {
    batchIndex: idx,
    batchCount: chunks.length,
    inputCount: chunk.length,
    companyIds: chunk.map((r) => r.companyId),
    liveWrite,
    writeMode,
    configuredWriteMode: cfg.writeMode,
    guard,
    endpoint: `${cfg.hubspot.apiBaseUrl}/crm/v3/objects/companies/batch/update`,
    payload: { inputs: chunk.map((r) => r.hubspotUpdate) },
  },
}));

// =====================================================================
// Simulate Write (Dry Run)
// Produces a HubSpot-shaped batch response WITHOUT calling the API.
// Reached whenever writeMode is sandbox, dry_run, updates_disabled,
// missing_token, blocked or no_changes.
// =====================================================================
return $input.all().map((item) => {
  const b = item.json;
  const now = new Date().toISOString();
  return {
    json: {
      simulated: true,
      batchIndex: b.batchIndex,
      writeMode: b.writeMode,
      status: b.inputCount ? 'SIMULATED' : 'NOTHING_TO_WRITE',
      startedAt: now,
      completedAt: now,
      results: (b.payload.inputs || []).map((i) => ({ id: i.id, properties: i.properties, simulated: true })),
      errors: [],
    },
  };
});

// =====================================================================
// Collect Write Results
// Reconciles batch responses (live or simulated) against the batches
// that were built, into one write summary. Handles HTTP 200 (COMPLETE),
// 207 multi-status (partial errors) and node-level request failures.
// =====================================================================
const batches = $('Build HubSpot Batch Payloads').all().map((i) => i.json);
const responses = $input.all().map((i) => i.json);
const first = batches[0] || { writeMode: 'no_changes', guard: {} };

const summary = {
  writeMode: first.writeMode,
  configuredWriteMode: first.configuredWriteMode,
  simulated: responses.every((r) => r.simulated === true),
  batches: batches.filter((b) => b.inputCount > 0).length,
  attempted: 0,
  succeeded: 0,
  simulatedWrites: 0,
  failed: 0,
  errors: [],
  guard: first.guard || {},
};

batches.forEach((b, idx) => {
  if (!b.inputCount) return;
  summary.attempted += b.inputCount;
  const r = responses[idx] || {};
  if (r.error) {
    summary.failed += b.inputCount;
    const msg = typeof r.error === 'string' ? r.error : (r.error.message || JSON.stringify(r.error));
    summary.errors.push({ batchIndex: b.batchIndex, message: String(msg).slice(0, 300) });
    return;
  }
  const ok = Array.isArray(r.results) ? r.results.length : 0;
  const errs = Array.isArray(r.errors) ? r.errors : [];
  if (r.simulated) summary.simulatedWrites += ok;
  else summary.succeeded += ok;
  summary.failed += r.simulated ? 0 : Math.max(0, b.inputCount - ok);
  for (const e of errs.slice(0, 5)) {
    summary.errors.push({ batchIndex: b.batchIndex, category: e.category || null, message: String(e.message || '').slice(0, 300) });
  }
});
summary.errors = summary.errors.slice(0, 10);
summary.status = summary.attempted === 0
  ? 'nothing_to_write'
  : summary.failed === 0 ? (summary.simulated ? 'simulated' : 'success') : (summary.succeeded > 0 ? 'partial_failure' : 'failed');

return [{ json: { writeSummary: summary } }];

// =====================================================================
// RevOps Summary & Slack Builder
// Builds run statistics and a Slack Block Kit message covering tier
// upgrades/downgrades, average score shift, top movers, data-quality
// gaps and the write execution result.
// =====================================================================
const cfg = $('Config & Safety Gate').first().json;
const rows = $('Account Scoring & Tier Recalibration Engine').all().map((i) => i.json).filter((r) => r.companyId);
const write = $input.first().json.writeSummary;
const MAX = cfg.slack.maxListItems;

const scored = rows.filter((r) => !r.insufficientData);
const insufficient = rows.filter((r) => r.insufficientData);
const upgrades = scored.filter((r) => r.tierChange === 'upgrade');
const downgrades = scored.filter((r) => r.tierChange === 'downgrade');
const initial = scored.filter((r) => r.tierChange === 'initial');
const held = scored.filter((r) => r.hysteresisHeld);
const withDelta = scored.filter((r) => r.scoreDelta !== null);
const drifted = withDelta.filter((r) => r.driftDetected);

const avg = (arr) => (arr.length ? Math.round((arr.reduce((a, b) => a + b, 0) / arr.length) * 10) / 10 : null);
const avgScore = avg(scored.map((r) => r.compositeScore));
const avgShift = avg(withDelta.map((r) => r.scoreDelta));
const avgAbsShift = avg(withDelta.map((r) => Math.abs(r.scoreDelta)));

const tierDistribution = { 'Tier 1': 0, 'Tier 2': 0, 'Tier 3': 0, Unqualified: 0 };
for (const r of scored) tierDistribution[r.tier] = (tierDistribution[r.tier] || 0) + 1;

const topMovers = [...withDelta].sort((a, b) => Math.abs(b.scoreDelta) - Math.abs(a.scoreDelta)).slice(0, MAX);

const fmtDelta = (d) => (d === null || d === undefined ? 'n/a' : `${d > 0 ? '+' : ''}${d}`);
const link = (r) => (cfg.hubspot.portalId
  ? `<https://app.hubspot.com/contacts/${cfg.hubspot.portalId}/record/0-2/${r.companyId}|${r.name}>`
  : r.name);
const truncate = (s, n = 2900) => (s.length > n ? `${s.slice(0, n - 20)}\n…(truncated)` : s);
const lines = (arr, fn) => (arr.length ? arr.slice(0, MAX).map(fn).join('\n') + (arr.length > MAX ? `\n…and ${arr.length - MAX} more` : '') : '_None this run_');

const modeBadge = cfg.sandboxMode ? '🧪 SANDBOX (synthetic fixture)' : cfg.dryRun ? '🔍 DRY RUN (live read, no writes)' : '🟢 LIVE';
const writeIcon = { success: '✅', simulated: '🧪', nothing_to_write: '➖', partial_failure: '⚠️', failed: '❌' }[write.status] || 'ℹ️';

const summary = {
  runId: cfg.runId,
  referenceDate: rows[0] ? rows[0].referenceDate : null,
  mode: modeBadge,
  companiesEvaluated: rows.length,
  companiesScored: scored.length,
  insufficientData: insufficient.length,
  upgrades: upgrades.length,
  downgrades: downgrades.length,
  initialAssignments: initial.length,
  heldByHysteresis: held.length,
  driftDetected: drifted.length,
  averageScore: avgScore,
  averageScoreShift: avgShift,
  averageAbsoluteScoreShift: avgAbsShift,
  tierDistribution,
  write,
};

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: '📊 Weekly ICP Score & Tier Recalibration', emoji: true } },
  { type: 'context', elements: [{ type: 'mrkdwn', text: `${modeBadge} · Run \`${cfg.runId}\` · Ref date ${summary.referenceDate ? summary.referenceDate.slice(0, 10) : 'n/a'}` }] },
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: `*Accounts evaluated*\n${rows.length}` },
      { type: 'mrkdwn', text: `*Scored / insufficient data*\n${scored.length} / ${insufficient.length}` },
      { type: 'mrkdwn', text: `*Tier upgrades ⬆️*\n${upgrades.length}` },
      { type: 'mrkdwn', text: `*Tier downgrades ⬇️*\n${downgrades.length}` },
      { type: 'mrkdwn', text: `*Avg score shift*\n${fmtDelta(avgShift)} pts (abs ${avgAbsShift ?? 'n/a'})` },
      { type: 'mrkdwn', text: `*Avg composite score*\n${avgScore ?? 'n/a'}` },
    ],
  },
  { type: 'section', text: { type: 'mrkdwn', text: `*Tier distribution:* T1 ${tierDistribution['Tier 1']} · T2 ${tierDistribution['Tier 2']} · T3 ${tierDistribution['Tier 3']} · Unqualified ${tierDistribution.Unqualified}${initial.length ? ` · ${initial.length} first-time assignment(s)` : ''}${held.length ? ` · ${held.length} held by hysteresis` : ''}` } },
  { type: 'divider' },
  { type: 'section', text: { type: 'mrkdwn', text: truncate(`*⬆️ Upgrades*\n${lines(upgrades, (r) => `• ${link(r)}: ${r.previousTier} → *${r.tier}* (${r.previousScore} → ${r.compositeScore}, ${fmtDelta(r.scoreDelta)})`)}`) } },
  { type: 'section', text: { type: 'mrkdwn', text: truncate(`*⬇️ Downgrades*\n${lines(downgrades, (r) => `• ${link(r)}: ${r.previousTier} → *${r.tier}* (${r.previousScore} → ${r.compositeScore}, ${fmtDelta(r.scoreDelta)})`)}`) } },
];
if (initial.length) {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: truncate(`*🆕 First-time scores*\n${lines(initial, (r) => `• ${link(r)}: *${r.tier}* (${r.compositeScore})`)}`) } });
}
blocks.push({ type: 'section', text: { type: 'mrkdwn', text: truncate(`*📈 Top score movers*\n${lines(topMovers, (r) => `• ${r.name}: ${fmtDelta(r.scoreDelta)} → ${r.compositeScore} (${r.tier})${r.hysteresisHeld ? ' _held_' : ''}`)}`) } });
if (insufficient.length) {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: truncate(`*🩺 Insufficient signal data (not written)*\n${lines(insufficient, (r) => `• ${r.name}: ${r.dataQualityFlags.join(', ')}`)}`) } });
}
blocks.push({ type: 'divider' });
blocks.push({
  type: 'section',
  text: {
    type: 'mrkdwn',
    text: truncate(`*${writeIcon} HubSpot write result:* \`${write.status}\` (mode \`${write.writeMode}\`)\n${write.simulated ? `Simulated ${write.simulatedWrites} (no API call)` : `Attempted ${write.attempted} · Succeeded ${write.succeeded} · Failed ${write.failed}`} · Batches ${write.batches}${write.guard && write.guard.blockReason ? `\n🛑 ${write.guard.blockReason}` : ''}${write.errors.length ? `\nFirst error: ${write.errors[0].message}` : ''}`),
  },
});
if (cfg.warnings.length) {
  blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: truncate(`⚠️ ${cfg.warnings.join(' | ')}`, 1900) }] });
}
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `n8n-hubspot-account-scoring-matrix-dynamic-recalculator · ${cfg.slack.channelLabel}` }] });

const text = `ICP recalibration ${cfg.runId}: ${upgrades.length} upgrades, ${downgrades.length} downgrades, avg shift ${fmtDelta(avgShift)} pts, write ${write.status}.`;

return [{ json: { summary, sendSlack: cfg.slackLive === true, slackPayload: { text, blocks: blocks.slice(0, 50) } } }];

// =====================================================================
// Slack Preview (Dry Run)
// Slack delivery is disabled (SEND_SLACK_ALERTS=false, DRY_RUN=true or
// no webhook URL). The Block Kit payload is kept in execution data so it
// can be pasted into Slack's Block Kit Builder for review.
// =====================================================================
const src = $input.first().json;
return [{ json: { slackStatus: 'preview_only', blockCount: src.slackPayload.blocks.length, slackPayload: src.slackPayload } }];

// =====================================================================
// Execution Summary & Audit
// Final, secret-free audit record of the run: effective config, safety
// state, per-account outcomes and write/alert delivery status.
// =====================================================================
const cfg = $('Config & Safety Gate').first().json;
const built = $('RevOps Summary & Slack Builder').first().json;
const rows = $('Account Scoring & Tier Recalibration Engine').all().map((i) => i.json).filter((r) => r.companyId);
const slackIn = $input.first().json;

let slackStatus;
if (slackIn.slackStatus === 'preview_only') slackStatus = 'preview_only';
else if (slackIn.error) slackStatus = `failed: ${String(slackIn.error.message || slackIn.error).slice(0, 200)}`;
else slackStatus = 'delivered';

const write = built.summary.write;
let status = 'completed';
if (write.status === 'failed' || write.status === 'partial_failure' || slackStatus.startsWith('failed')) status = 'completed_with_errors';
if (write.guard && write.guard.blockReason) status = 'completed_writes_blocked';

const audit = {
  auditVersion: '1.0.0',
  workflow: 'n8n-hubspot-account-scoring-matrix-dynamic-recalculator',
  runId: cfg.runId,
  status,
  runStartedAt: cfg.runStartedAt,
  runCompletedAt: new Date().toISOString(),
  referenceDate: built.summary.referenceDate,
  safety: {
    sandboxMode: cfg.sandboxMode,
    dryRun: cfg.dryRun,
    scoreUpdateEnabled: cfg.scoreUpdateEnabled,
    sendSlackAlerts: cfg.sendSlackAlerts,
    sendAuditWebhook: cfg.sendAuditWebhook,
    envAccessible: cfg.envAccessible,
    effectiveWriteMode: write.writeMode,
    credentialsPresent: cfg.credentialsPresent,
    circuitBreaker: write.guard,
  },
  scoringConfig: {
    weights: cfg.scoring.weights,
    tiers: cfg.scoring.tiers,
    driftThreshold: cfg.scoring.driftThreshold,
    minComponents: cfg.scoring.minComponents,
    writePolicy: cfg.scoring.writePolicy,
  },
  ingest: rows[0] ? rows[0]._ingest : null,
  results: built.summary,
  delivery: { slack: slackStatus, auditWebhook: cfg.auditWebhookLive ? 'pending' : 'disabled' },
  accounts: rows.map((r) => ({
    companyId: r.companyId,
    name: r.name,
    previousScore: r.previousScore,
    newScore: r.compositeScore,
    scoreDelta: r.scoreDelta,
    previousTier: r.previousTier,
    newTier: r.tier,
    tierChange: r.tierChange,
    dataCompleteness: r.dataCompleteness,
    flags: r.dataQualityFlags,
    written: r.shouldWrite && ['live'].includes(write.writeMode) && write.status === 'success',
    writeReason: r.writeReason,
  })),
  warnings: cfg.warnings,
};

return [{ json: { sendAuditWebhook: cfg.auditWebhookLive === true, audit } }];
